set
  title = 'Communication, Civic Life, and Culture',
  goal = 'Communication, Civic Life, and Culture',
  summary = 'Examine how communication shapes democratic life, public culture, media systems, identity, disagreement, civic knowledge, and collective action. Students learn to analyze public communication and design ethical civic communication interventions.',
  data = $ccivjson${"slug": "communication-civic-life-and-culture", "title": "Communication, Civic Life, and Culture", "description": "Examine how communication shapes democratic life, public culture, media systems, identity, disagreement, civic knowledge, and collective action. Students learn to analyze public communication and design ethical civic communication interventions.", "topics": [{"id": "ee00bc86-6a17-4f17-8d95-8a0c40bf47bc", "type": "topic", "title": "Communication, Democracy, and Civic Life", "description": "This opening section asks how communication makes public life possible. Students learn that democracy depends not only on institutions, but also on shared meanings, channels, norms, and habits of participation.", "children": [{"id": "413329ec-0e96-460d-aa46-d48230fc0ff6", "type": "subtopic", "title": "Communication as civic infrastructure", "children": [{"id": "45375ca6-504a-4851-94e5-809ffdd0d93e", "type": "concept", "title": "public voice"}, {"id": "73bdf175-4d95-4860-975d-393068137d05", "type": "concept", "title": "civic listening"}, {"id": "62c76ada-c5ff-4dd1-8307-a2d39df0c36b", "type": "concept", "title": "participation norms"}, {"id": "0c5173be-8578-4158-a467-2a840f0c96fb", "type": "concept", "title": "institutional trust"}], "description": "Why it matters: Communication links citizens, institutions, communities, and movements into a public world where collective decisions can be debated."}, {"id": "71d5c863-abcd-4b4f-94a7-dd1b1efb773c", "type": "subtopic", "title": "Democratic communication norms", "children": [{"id": "89dc5f80-4be7-4e32-b5c5-4617e6b45be8", "type": "concept", "title": "openness"}, {"id": "a688393d-0da6-4ea9-8b63-490b671035f1", "type": "concept", "title": "reason-giving"}, {"id": "be43cca4-45e1-44a8-aef6-659a51ccaf0b", "type": "concept", "title": "accountability"}, {"id": "ac30f5e7-efa4-4273-af7f-ffd9840aab9e", "type": "concept", "title": "respect across difference"}], "description": "Why it matters: Students learn the standards that make public disagreement more productive and less corrosive."}, {"id": "d2b2be47-5c44-455c-9395-8e186703424d", "type": "subtopic", "title": "Civic agency", "children": [{"id": "15212951-8562-4041-9e93-b246eb01631e", "type": "concept", "title": "advocacy"}, {"id": "e081fecf-a4da-4ffb-a6b8-aaebdd09d731", "type": "concept", "title": "coalition building"}, {"id": "f9e5ebb1-53a0-4e98-9827-e8704d0f4419", "type": "concept", "title": "public problem solving"}, {"id": "3a8ac531-231f-41fc-8144-3f4e730aa0e2", "type": "concept", "title": "community storytelling"}], "description": "Why it matters: The point is to understand how people use messages, media, and relationships to act in public."}]}, {"id": "b538ed70-a201-4af2-a99d-fdd4a16a64ce", "type": "topic", "title": "Public Sphere, Publics, and Counterpublics", "description": "Public sphere theory gives students language for how issues become public, whose voices count, and how alternative publics challenge exclusion.", "children": [{"id": "e561a37c-b1fc-4a82-98f2-3d7b64ee2092", "type": "subtopic", "title": "Classical public sphere theory", "children": [{"id": "15a7e4bb-a6ff-4b61-98db-e662ec9ad3c0", "type": "concept", "title": "Habermas"}, {"id": "442072fe-53fb-4626-b7c0-23170823c38f", "type": "concept", "title": "salons and print culture"}, {"id": "11f3912f-2a3f-4a7a-b24a-08db10a4eac6", "type": "concept", "title": "access"}, {"id": "98af36f9-31cc-4064-ad8a-3a302e06b7f2", "type": "concept", "title": "public opinion"}], "description": "Why it matters: Students use foundational theory to examine how rational-critical debate became an ideal of democratic life."}, {"id": "cfced968-ded7-4c39-be4d-c4feef42c0b3", "type": "subtopic", "title": "Publics and counterpublics", "children": [{"id": "c8a274f3-de0d-491b-9851-35ea56592179", "type": "concept", "title": "counterpublics"}, {"id": "444d45c4-c669-4349-bbd3-4323d32df1cf", "type": "concept", "title": "subaltern publics"}, {"id": "ed43fdc0-e2c4-4d7a-bdd8-d7f0e5cc35f0", "type": "concept", "title": "movement media"}, {"id": "a49f6704-fc6b-4b65-a248-74ce680ec838", "type": "concept", "title": "community forums"}], "description": "Why it matters: Public life is plural, with marginalized groups often creating their own spaces for recognition and action."}, {"id": "1440382a-4918-4ec2-9a1d-91e0dbdf0ae2", "type": "subtopic", "title": "Public problems and agenda formation", "children": [{"id": "eb1fe9ca-57d4-4497-a819-e734d848758c", "type": "concept", "title": "issue emergence"}, {"id": "3ecba4f4-b5f1-4daa-86d5-a15712509932", "type": "concept", "title": "framing"}, {"id": "42fd689d-0a01-4991-8d7f-43dfbb5814cd", "type": "concept", "title": "agenda setting"}, {"id": "449062e0-412b-42f5-bcf7-2c65666dc7ed", "type": "concept", "title": "claims-making"}], "description": "Why it matters: Students analyze how private troubles are framed as shared civic issues."}]}, {"id": "32496e17-a890-4155-9aca-eabd4ece7287", "type": "topic", "title": "Culture, Meaning, and Everyday Communication", "description": "Culture shapes the meanings people bring to messages, rituals, images, humor, conflict, and belonging. This section treats culture as lived practice rather than decoration.", "children": [{"id": "5f910129-1961-42a0-9593-df1eac976b37", "type": "subtopic", "title": "Culture as shared meaning", "children": [{"id": "03ee762b-6ba0-489b-bba7-ac3f1907c74a", "type": "concept", "title": "symbols"}, {"id": "62dfc904-1c7b-4755-b07c-7ff894f2c2c6", "type": "concept", "title": "rituals"}, {"id": "25399262-b85b-43c4-b4cd-03e5ef9a3a04", "type": "concept", "title": "norms"}, {"id": "ec31a034-c9b4-4ab6-9c18-5ac80b7668c8", "type": "concept", "title": "interpretive communities"}], "description": "Why it matters: Students learn how symbols, stories, and routines organize social life."}, {"id": "8b153b49-98f9-44dc-8483-45849b0c85d0", "type": "subtopic", "title": "Popular culture and civic life", "children": [{"id": "b7a0e2a7-d4d7-4961-a046-479110011e69", "type": "concept", "title": "celebrity politics"}, {"id": "80702bc6-fa99-41f3-b3ec-e146ac62c213", "type": "concept", "title": "memes"}, {"id": "b2ea05df-69ba-4963-81db-c9adc47c8031", "type": "concept", "title": "fan activism"}, {"id": "92c4b826-969a-46e4-a308-365fd3fd9d25", "type": "concept", "title": "cultural memory"}], "description": "Why it matters: Entertainment, memes, sports, and fandom can carry political values and public identities."}, {"id": "3ce02029-71b2-4f14-b918-7b893268218e", "type": "subtopic", "title": "Cultural power", "children": [{"id": "d71e5906-7a53-45cc-a714-186b95e33937", "type": "concept", "title": "hegemony"}, {"id": "9bbbea9b-2aec-48ed-9fcc-5d2f6e62538f", "type": "concept", "title": "resistance"}, {"id": "c2e6bf7f-acd8-43e7-8785-aeeb46cf5478", "type": "concept", "title": "ideology"}, {"id": "21687fe9-6fc2-44fe-9e67-679d588c16fa", "type": "concept", "title": "cultural production"}], "description": "Why it matters: Students examine how some meanings become dominant while others are contested."}]}, {"id": "e5fdc38f-95cb-48eb-b0ea-80f15b100178", "type": "topic", "title": "Media, Citizenship, and Public Opinion", "description": "Media systems shape what citizens know, what they notice, and how they imagine political community. Students learn to connect institutions, audiences, and civic consequences.", "children": [{"id": "42c33b47-bf2c-4398-946c-c6778c0267ec", "type": "subtopic", "title": "Media institutions", "children": [{"id": "00d2cf4e-104f-4a0a-a5fb-83e11754a352", "type": "concept", "title": "news values"}, {"id": "ebad6f5a-11a2-4064-8daa-7435ab13bb80", "type": "concept", "title": "gatekeeping"}, {"id": "9bf5a081-b5c7-4475-81f7-8f83ea829df2", "type": "concept", "title": "media ownership"}, {"id": "42201a07-3991-4c30-b181-60fca7c33fcd", "type": "concept", "title": "platform dependence"}], "description": "Why it matters: Ownership, routines, professional norms, and economic pressures affect public information."}, {"id": "2db99c0d-efe2-462e-ab9f-ffd36d83bd91", "type": "subtopic", "title": "Citizenship and information", "children": [{"id": "5168a06c-2555-4353-b2de-a39b54cfcd0a", "type": "concept", "title": "informed citizenship"}, {"id": "25401236-1c4d-458a-88f0-eadd641d51fe", "type": "concept", "title": "news avoidance"}, {"id": "4d3cd0e6-ae60-4a26-9ea2-bfa5efd707f9", "type": "concept", "title": "knowledge gaps"}, {"id": "97cf152e-091c-4e7e-960a-957671529857", "type": "concept", "title": "civic engagement"}], "description": "Why it matters: Civic participation depends on access to credible information and opportunities for voice."}, {"id": "0f6b0cfe-9685-49e0-9b53-8dabe99fab4f", "type": "subtopic", "title": "Public opinion", "children": [{"id": "710fdb1c-54d4-46b7-8e85-b15b7aeec73d", "type": "concept", "title": "polling"}, {"id": "341dfdf4-c390-4474-a8a6-d47d32283a46", "type": "concept", "title": "spiral of silence"}, {"id": "6db3d4d5-fec2-48d5-9aa8-3a1f3d89f42b", "type": "concept", "title": "priming"}, {"id": "1a2fff22-4439-4373-9cca-912aca1e6e68", "type": "concept", "title": "public mood"}], "description": "Why it matters: Students learn how opinion is formed, measured, represented, and used in democratic life."}]}, {"id": "4b3fc0ed-6e78-4e40-a891-6978bf637ee0", "type": "topic", "title": "Identity, Race, Representation, and Power", "description": "Representation is not only about visibility; it shapes social reality, authority, aspiration, and belonging. This topic centers identity, inequality, and media power.", "children": [{"id": "30e6bdf4-88eb-4031-a011-554557fed84b", "type": "subtopic", "title": "Representation and stereotyping", "children": [{"id": "ec1db496-f3d4-4efb-be97-4e483e5ea79c", "type": "concept", "title": "stereotypes"}, {"id": "ea4e906c-08e2-4075-8aa9-dde3caa9543d", "type": "concept", "title": "symbolic annihilation"}, {"id": "b15ac8a9-731d-4d64-a048-ca3f739197d7", "type": "concept", "title": "tokenism"}, {"id": "2a27d20d-f167-43b9-85ea-d59bc7317c3e", "type": "concept", "title": "counter-stereotypes"}], "description": "Why it matters: Students evaluate how repeated portrayals influence public perception and policy imagination."}, {"id": "d9b4eed2-57a0-436a-baf4-d255c65609d3", "type": "subtopic", "title": "Race, gender, class, sexuality, and disability", "children": [{"id": "a7dab5fc-69a5-45d1-968c-1fdc4bff51ae", "type": "concept", "title": "intersectionality"}, {"id": "ce4dbc8a-5fdb-43ab-9f4e-57c192399b09", "type": "concept", "title": "racial formation"}, {"id": "c2b41c2d-6ee3-404f-ad61-3dd8e86f0272", "type": "concept", "title": "gender performance"}, {"id": "96eef3a6-b59a-4ddc-a7c3-4dfbe3713643", "type": "concept", "title": "ableism in media"}], "description": "Why it matters: Identity categories intersect in communication, producing different experiences of voice and recognition."}, {"id": "1c119d31-7bd7-4bee-b661-2eb103f9ea39", "type": "subtopic", "title": "Power and recognition", "children": [{"id": "44f7cbce-50d8-4078-b71a-76c3e77047d0", "type": "concept", "title": "voice"}, {"id": "f1c46d07-1273-4376-8c3b-61d3d12f4548", "type": "concept", "title": "visibility"}, {"id": "6475490c-6313-4763-bfcc-a5aa0b301dc5", "type": "concept", "title": "misrecognition"}, {"id": "0b5194eb-4dbf-4a72-9103-31c8cf4c3229", "type": "concept", "title": "narrative power"}], "description": "Why it matters: Students study whose stories become common sense and whose expertise is dismissed."}]}, {"id": "c88f4b27-efe4-49d1-b9cc-e65978f63ea3", "type": "topic", "title": "Political Communication, Campaigns, and Public Discourse", "description": "Political communication shows how candidates, institutions, journalists, advocates, and citizens compete to define reality and mobilize publics.", "children": [{"id": "490a89f9-b3cb-4e6b-90cd-fb6f5cc075a6", "type": "subtopic", "title": "Campaign communication", "children": [{"id": "28c4d535-3e03-47fc-9089-978e38ce9ee5", "type": "concept", "title": "message discipline"}, {"id": "ff0b78bc-0287-4f18-8371-0b115ddddb65", "type": "concept", "title": "advertising"}, {"id": "f884fa8d-0ccc-451c-8e1a-f932bd53e1a5", "type": "concept", "title": "debates"}, {"id": "7e272aa2-6709-4473-8fd4-dcd5a7e512b5", "type": "concept", "title": "microtargeting"}], "description": "Why it matters: Students study how campaigns construct messages, target audiences, and manage attention."}, {"id": "d22b6c7e-66db-4d03-b317-84b6d4ca3a95", "type": "subtopic", "title": "News, politics, and polarization", "children": [{"id": "18afe98d-0e11-42f4-916d-24c4100d0149", "type": "concept", "title": "partisan media"}, {"id": "238c8af2-97b8-4624-a3bb-d78b63a8777d", "type": "concept", "title": "echo chambers"}, {"id": "fcf963b8-f917-41be-a192-218383be283e", "type": "concept", "title": "selective exposure"}, {"id": "73f48d64-feb7-4c0c-af4f-d55642228f32", "type": "concept", "title": "affective polarization"}], "description": "Why it matters: Political media can inform, mobilize, fragment, or intensify conflict."}, {"id": "48a5962d-6064-49ab-aee4-b644a923dc3e", "type": "subtopic", "title": "Public discourse analysis", "children": [{"id": "8a772ac2-ba26-49a6-ab8b-6152c03d0ae7", "type": "concept", "title": "claims"}, {"id": "245f804d-8e57-4bec-8d74-d75a5fd532a3", "type": "concept", "title": "warrants"}, {"id": "35abdf73-1f7b-4413-bae8-7ab9636a5f94", "type": "concept", "title": "metaphor"}, {"id": "78bfa325-9958-42e2-a68e-8e662e6d6e60", "type": "concept", "title": "strategic ambiguity"}], "description": "Why it matters: Students learn to read speeches, debates, and media texts for claims, values, and implied audiences."}]}, {"id": "0853be95-5d51-4f79-a80a-01b984dec746", "type": "topic", "title": "Rhetoric, Persuasion, and Argumentation", "description": "Rhetoric gives students tools for understanding how public messages move audiences. The goal is not manipulation, but ethical analysis and responsible influence.", "children": [{"id": "b284c484-b1ac-4296-8be9-39119fe907de", "type": "subtopic", "title": "Classical rhetoric", "children": [{"id": "19b7dc3b-3855-45bc-a9c1-dee6b0eef9f8", "type": "concept", "title": "ethos"}, {"id": "660da5de-b30d-4f4f-9af1-40155d033c58", "type": "concept", "title": "pathos"}, {"id": "bc9561c6-5521-4e79-ae83-74c5ea8511ba", "type": "concept", "title": "logos"}, {"id": "1e292163-5163-402c-acfd-081569680197", "type": "concept", "title": "kairos"}], "description": "Why it matters: Students learn durable concepts for analyzing speaker credibility, emotional appeal, and reasoning."}, {"id": "1e21e147-62ec-45d2-b5da-bb9232dee0f3", "type": "subtopic", "title": "Argument quality", "children": [{"id": "edb3dc21-7d26-4032-b58f-5b3dfacf6cca", "type": "concept", "title": "claims"}, {"id": "1a63a0e6-9a86-47be-9eb3-8a6e7ee00e33", "type": "concept", "title": "evidence"}, {"id": "3bca7733-5023-49a9-9728-4cb2ef5724df", "type": "concept", "title": "fallacies"}, {"id": "5bd87fbc-a77a-484a-bdc7-a88be5e6b3b4", "type": "concept", "title": "rebuttal"}], "description": "Why it matters: Strong civic argument depends on evidence, warrants, fair opposition, and clear stakes."}, {"id": "841fb509-f007-432c-b3f2-4d0fb3afd97f", "type": "subtopic", "title": "Persuasion ethics", "children": [{"id": "2256a613-a911-46a0-aea1-ea9449ed7b27", "type": "concept", "title": "transparency"}, {"id": "68c40582-321b-4fa4-86fd-b4282deac47a", "type": "concept", "title": "fear appeals"}, {"id": "8b81fef4-d811-481b-8581-a15bd0fc39d6", "type": "concept", "title": "manipulation"}, {"id": "bf201106-c909-4b33-a26a-621c6fefd59f", "type": "concept", "title": "public interest"}], "description": "Why it matters: Students distinguish ethical advocacy from coercion, deception, and propaganda."}]}, {"id": "5b1e23cf-34b9-4b0e-aa69-ff8b669c7245", "type": "topic", "title": "Social Movements, Advocacy, and Collective Action", "description": "Movements use communication to name injustice, build solidarity, recruit participants, and pressure institutions. Students study both strategy and culture.", "children": [{"id": "5033325b-930b-40b0-8b43-a61497a60140", "type": "subtopic", "title": "Movement framing", "children": [{"id": "6db34a56-4aae-4b12-98be-06ee951cc94c", "type": "concept", "title": "diagnostic frames"}, {"id": "fbd6b714-e34c-42c5-a558-df58cad9223e", "type": "concept", "title": "prognostic frames"}, {"id": "aff2cb16-11f0-46e9-b04e-b363cb717479", "type": "concept", "title": "motivational frames"}, {"id": "beb6e42f-3e01-48a0-84cc-6e7a7269b12e", "type": "concept", "title": "frame resonance"}], "description": "Why it matters: Frames help people interpret grievances, identify causes, and imagine action."}, {"id": "1558260e-e386-4e9e-8392-24813284615d", "type": "subtopic", "title": "Collective identity", "children": [{"id": "7fd9d896-52f9-4961-8d94-e8feb950f580", "type": "concept", "title": "solidarity"}, {"id": "d864ba95-1bba-4f6f-bba5-650d5a64e0a3", "type": "concept", "title": "movement culture"}, {"id": "a6c09c40-f75a-4ff1-8b01-013f263466ac", "type": "concept", "title": "chants and visuals"}, {"id": "aafe2317-7a6e-46fd-94c8-ce340a5aff0b", "type": "concept", "title": "emotional energy"}], "description": "Why it matters: Movements sustain participation through shared stories, symbols, rituals, and belonging."}, {"id": "e892db56-2faa-4ade-8543-0e1916e95ae5", "type": "subtopic", "title": "Advocacy strategy", "children": [{"id": "53f83800-213d-47d7-9c28-6e0073b68c49", "type": "concept", "title": "stakeholder mapping"}, {"id": "a60c4e5a-77c5-447d-aca0-8fe15a75ea28", "type": "concept", "title": "calls to action"}, {"id": "e4306a8c-572d-4c97-8416-d10ae2cc5cd6", "type": "concept", "title": "coalitions"}, {"id": "b4e56ef2-387f-4aab-9811-534daf319dbd", "type": "concept", "title": "campaign evaluation"}], "description": "Why it matters: Students connect message design to goals, audiences, channels, and power analysis."}]}, {"id": "1999ed8b-08d6-47d1-b1d5-04315ea5d01b", "type": "topic", "title": "Globalization, Intercultural Communication, and Transnational Publics", "description": "Civic life is shaped by migration, diaspora, global media, and cross-border problems. Students learn to communicate across culture without flattening difference.", "children": [{"id": "640657ff-05f8-4114-a444-4e0c8e8531b5", "type": "subtopic", "title": "Intercultural competence", "children": [{"id": "3a5ef060-0ec4-487a-a6fc-284724f7d351", "type": "concept", "title": "cultural humility"}, {"id": "fd2f8269-a454-4d45-a49d-507e3710486a", "type": "concept", "title": "high-context and low-context patterns"}, {"id": "ec709f6c-55f4-48d8-ae93-f305ab45de1a", "type": "concept", "title": "translation"}, {"id": "ed8c07a3-4e7b-406d-8e17-e0fffc09daf7", "type": "concept", "title": "listening across difference"}], "description": "Why it matters: Students practice interpreting communication in relation to context, identity, power, and history."}, {"id": "669d9037-0da5-4053-859c-8e713db040f2", "type": "subtopic", "title": "Global media flows", "children": [{"id": "8f909412-a4fd-4a7c-a92d-74a094033560", "type": "concept", "title": "cultural hybridity"}, {"id": "e252097a-2091-4014-8ad0-484f0a389672", "type": "concept", "title": "soft power"}, {"id": "b8f18e68-8ac7-4805-bf61-fa04dadadceb", "type": "concept", "title": "diaspora media"}, {"id": "f77a0637-3818-419a-998d-d8289bec28c0", "type": "concept", "title": "platform globalization"}], "description": "Why it matters: Media circulate images, values, conflicts, and solidarities across borders."}, {"id": "6d415d5e-0440-4572-8424-65713c85a715", "type": "subtopic", "title": "Transnational civic issues", "children": [{"id": "20479e01-933f-4a57-ae1e-521a20f44824", "type": "concept", "title": "global publics"}, {"id": "e0aebe8e-7b67-432e-9ce4-58c5f560c1b8", "type": "concept", "title": "NGO communication"}, {"id": "6a28c42b-7211-400d-8988-416b2b1ca836", "type": "concept", "title": "risk translation"}, {"id": "4d9283ea-fdf4-47e3-b0a6-f41998733e82", "type": "concept", "title": "solidarity narratives"}], "description": "Why it matters: Climate, health, migration, war, and human rights require communication beyond the nation-state."}]}, {"id": "fa362b44-855a-4a2d-aaf8-2ee8c9546cfe", "type": "topic", "title": "Digital Civic Engagement and Networked Publics", "description": "Digital platforms have changed how people assemble, learn, argue, organize, and perform citizenship. Students examine both participatory potential and structural risk.", "children": [{"id": "7a300736-b7ea-4d23-863e-2e79fdd12cae", "type": "subtopic", "title": "Networked publics", "children": [{"id": "c4347770-e52f-4e69-a0c2-561b01a65526", "type": "concept", "title": "platform affordances"}, {"id": "878cfba8-6e07-4c5b-bfeb-99d73ce148c4", "type": "concept", "title": "context collapse"}, {"id": "8f63498f-1ac7-4f8c-8faf-3805a9179831", "type": "concept", "title": "virality"}, {"id": "9943350f-5f7b-4d07-8e8c-3b3e895b93f3", "type": "concept", "title": "network effects"}], "description": "Why it matters: Online publics are shaped by persistence, visibility, spreadability, and searchability."}, {"id": "eb516cbb-e5b7-46a4-8cad-5f7a864a7ec5", "type": "subtopic", "title": "Digital participation", "children": [{"id": "30fa5e57-e7d3-459c-9bee-19a3393b3f52", "type": "concept", "title": "hashtag activism"}, {"id": "357703bd-a86e-44e2-ad2b-01aeaf37cd97", "type": "concept", "title": "participatory culture"}, {"id": "c551b9e6-da55-4960-bc95-83a55c5584ba", "type": "concept", "title": "civic crowdfunding"}, {"id": "93707b56-5976-48d6-8e1d-369e3891c0a8", "type": "concept", "title": "online communities"}], "description": "Why it matters: Students analyze online petitions, hashtags, livestreams, forums, and creator-led civic work."}, {"id": "0cecce68-e2dc-4e57-9d7d-c3303789c794", "type": "subtopic", "title": "Platform power", "children": [{"id": "775f64f6-fbcd-42e1-aaea-75d74facdcca", "type": "concept", "title": "algorithmic curation"}, {"id": "01fd0d3f-5497-48f0-a89f-bd80d1079b4b", "type": "concept", "title": "content moderation"}, {"id": "07a4f872-e6ad-46df-a47e-88ee2764eff8", "type": "concept", "title": "surveillance capitalism"}, {"id": "0c589f81-5686-41b7-943b-039eb1974aa7", "type": "concept", "title": "creator economy"}], "description": "Why it matters: Digital civic life is governed by algorithms, moderation, data extraction, and business models."}]}, {"id": "aedabfd4-f6f4-47e6-859b-5c2d9c13e354", "type": "topic", "title": "Media Literacy, Misinformation, and Civic Knowledge", "description": "Civic communication requires epistemic responsibility: knowing how to evaluate claims, trace sources, and participate without spreading harm.", "children": [{"id": "79ef6fc8-5cd3-40af-926e-8b8fb3a64b22", "type": "subtopic", "title": "Information verification", "children": [{"id": "1e712804-01ce-4017-820c-db76c7e89bc8", "type": "concept", "title": "lateral reading"}, {"id": "751284e6-51a8-47e9-b8f6-05e6336a23f3", "type": "concept", "title": "source tracing"}, {"id": "d6186545-27f9-47e2-a8f6-cc1cabb48375", "type": "concept", "title": "image verification"}, {"id": "6bc3a150-01b7-4413-a764-1c52cf739dfd", "type": "concept", "title": "fact-checking"}], "description": "Why it matters: Students learn practical routines for checking claims before sharing or citing them."}, {"id": "e1614611-81f5-40bb-b9cf-4bda7640dc30", "type": "subtopic", "title": "Misinformation and disinformation", "children": [{"id": "3c24fcc0-9178-4de3-a8e9-cf06426c6a05", "type": "concept", "title": "misinformation"}, {"id": "22077379-7dfd-46a7-9f05-6ee946c35580", "type": "concept", "title": "disinformation"}, {"id": "fca4a57c-3d98-4fda-8e0a-5a166e31b007", "type": "concept", "title": "malinformation"}, {"id": "2f00631b-e4ca-4d56-a7af-93d716a21246", "type": "concept", "title": "bots and astroturfing"}], "description": "Why it matters: Students distinguish mistakes, manipulation, propaganda, and coordinated influence operations."}, {"id": "4be9292a-d73b-401d-a475-e3561d0d5771", "type": "subtopic", "title": "Civic knowledge ecosystems", "children": [{"id": "c80a85cf-dc00-4981-8d71-f8832c40fb49", "type": "concept", "title": "trust"}, {"id": "1baff097-95ce-480a-89be-6381cb7f70f9", "type": "concept", "title": "expertise"}, {"id": "e6a7fd50-a30f-40ce-8c2e-07fe07f9f202", "type": "concept", "title": "local news"}, {"id": "91b2d87c-ab84-4c59-b3ee-c86512dd5385", "type": "concept", "title": "knowledge inequality"}], "description": "Why it matters: The course examines how schools, journalism, libraries, platforms, and communities support public knowledge."}]}, {"id": "1cd6aab8-0c84-4cdb-8211-cebc70ee791e", "type": "topic", "title": "Communication Ethics, Law, and Platform Governance", "description": "Ethics and law define the boundaries of public communication, but also reveal unresolved tensions among speech, harm, privacy, equality, and power.", "children": [{"id": "4e88fd24-322e-4243-a559-df3f3576e13d", "type": "subtopic", "title": "Free speech and democratic values", "children": [{"id": "f1412e37-aa42-482c-ba2d-c2be95059f3f", "type": "concept", "title": "First Amendment traditions"}, {"id": "82837c50-130d-42f3-89bb-491368e8054d", "type": "concept", "title": "censorship"}, {"id": "258c466b-8cc2-46df-a46c-ad6892b17275", "type": "concept", "title": "hate speech debates"}, {"id": "93c6f0e8-9faa-4094-86ae-141251dd347f", "type": "concept", "title": "prior restraint"}], "description": "Why it matters: Students examine why speech protections matter and where conflicts arise."}, {"id": "8babfb5a-c6a5-42c9-a879-0aca727a5796", "type": "subtopic", "title": "Privacy, data, and consent", "children": [{"id": "0fc9d968-383c-46ff-add2-b3b76bd67551", "type": "concept", "title": "data privacy"}, {"id": "4706824d-7240-4e5c-b3ae-f38114476e19", "type": "concept", "title": "consent"}, {"id": "d8f7041f-d4b3-43f0-be66-dcdd0c9da563", "type": "concept", "title": "doxxing"}, {"id": "44b47788-5fe7-4b6f-9477-78e05561afa7", "type": "concept", "title": "AI-generated media"}], "description": "Why it matters: Digital civic life raises questions about surveillance, profiling, and informed participation."}, {"id": "6ebe75cf-fc45-4f50-8551-8292e075e5a3", "type": "subtopic", "title": "Platform governance", "children": [{"id": "09b11b18-feca-4b3e-9f45-07f501dd61e8", "type": "concept", "title": "terms of service"}, {"id": "f5f44f6c-ab7c-49ee-87c3-9b1058b70a3f", "type": "concept", "title": "content moderation"}, {"id": "d104695b-b746-45bf-8c40-ae3863832f03", "type": "concept", "title": "transparency reports"}, {"id": "39aba31f-6c56-47bf-9fad-c191c421aeb4", "type": "concept", "title": "policy tradeoffs"}], "description": "Why it matters: Students assess who should moderate, rank, remove, or amplify public communication."}]}, {"id": "16b3d1d1-0245-4f58-a320-3eda62d83285", "type": "topic", "title": "Research Methods for Civic Communication", "description": "Research methods help students move from opinion to evidence. This section prepares students to analyze audiences, texts, platforms, and civic effects responsibly.", "children": [{"id": "77f4ae81-f1a6-4aba-8ad2-2e609c581083", "type": "subtopic", "title": "Research questions and design", "children": [{"id": "a27a508e-721f-41ce-bf7e-4da881b9a7f3", "type": "concept", "title": "conceptualization"}, {"id": "b5cd7a0f-ae85-425a-b27f-47afd45b8439", "type": "concept", "title": "operationalization"}, {"id": "2e5b583c-69be-4893-968f-89a40e1e7be0", "type": "concept", "title": "sampling"}, {"id": "abb39b06-59c2-4772-924d-56e800eedef2", "type": "concept", "title": "ethics review"}], "description": "Why it matters: A good civic communication study begins with a focused question and appropriate evidence."}, {"id": "0dd03e43-79db-4855-92b9-3df0b77a55e7", "type": "subtopic", "title": "Textual and content analysis", "children": [{"id": "7258253f-a197-45a1-8f23-da160ae02ca7", "type": "concept", "title": "coding"}, {"id": "2eb43ae6-4266-4610-b933-562116d17ca7", "type": "concept", "title": "themes"}, {"id": "cd0f5469-e8f7-487a-86f9-b1a0425e2be2", "type": "concept", "title": "reliability"}, {"id": "d646432e-6955-47f5-aede-7b1ef49728cd", "type": "concept", "title": "discourse analysis"}], "description": "Why it matters: Students learn systematic ways to interpret media texts, speeches, posts, and campaigns."}, {"id": "96251c31-0d93-4db0-93b8-85a11ec70584", "type": "subtopic", "title": "Audience and community research", "children": [{"id": "285c1901-d549-40c5-a8bf-59df50efcbf6", "type": "concept", "title": "survey design"}, {"id": "a91acc27-3739-4407-ae09-66c047c8eae6", "type": "concept", "title": "interviews"}, {"id": "53ea7522-5483-4b4d-8d18-f171948cc64a", "type": "concept", "title": "focus groups"}, {"id": "3d794eb7-cc26-4d4b-a627-74354e625562", "type": "concept", "title": "participant observation"}], "description": "Why it matters: Surveys, interviews, focus groups, and observation help students understand publics rather than assume them."}]}, {"id": "047fe729-8bb9-4fac-bca9-d912310721e3", "type": "topic", "title": "Dialogue, Deliberation, Conflict, and Facilitation", "description": "Civic life requires people to communicate across disagreement. Students learn practices for dialogue, deliberation, repair, and collective decision-making.", "children": [{"id": "4fee6a8f-64ae-4f20-8115-41bde492fe2e", "type": "subtopic", "title": "Dialogue versus debate", "children": [{"id": "41e6a65e-df0f-44c8-b011-f524a5f3a492", "type": "concept", "title": "dialogue norms"}, {"id": "f3f92a8c-9a1f-4aa8-8fb5-379b5450a3fe", "type": "concept", "title": "active listening"}, {"id": "38d95e3e-eded-4366-838a-fec5413a7142", "type": "concept", "title": "curiosity"}, {"id": "d2797da4-2f13-4ccf-a0c1-61acf2c56ed5", "type": "concept", "title": "story exchange"}], "description": "Why it matters: Students distinguish winning an argument from building understanding and shared judgment."}, {"id": "662d98b3-9e03-4c65-aafe-1017d2f15d9e", "type": "subtopic", "title": "Deliberative design", "children": [{"id": "85eca5e7-0cfb-46cf-918b-b0f19d39f970", "type": "concept", "title": "deliberative forums"}, {"id": "05016b1a-8531-4254-9401-5d5afb3f6b4b", "type": "concept", "title": "choice work"}, {"id": "9758aae5-39ad-402f-a618-54b99a8c0e97", "type": "concept", "title": "tradeoffs"}, {"id": "bb61489c-1f97-4d8e-8378-99aa21790345", "type": "concept", "title": "public judgment"}], "description": "Why it matters: Public deliberation requires issue framing, balanced information, facilitation, and follow-through."}, {"id": "a68cacd3-a58c-4e43-97f6-e44546e8e754", "type": "subtopic", "title": "Conflict communication", "children": [{"id": "2a309478-0617-41b3-831f-01d9a5a35aeb", "type": "concept", "title": "reframing"}, {"id": "b4c2935e-aded-441b-8a0a-556cd8958a60", "type": "concept", "title": "mediation basics"}, {"id": "12e61207-a2f7-48a6-9183-8174825686e6", "type": "concept", "title": "face-saving"}, {"id": "8dcb4972-8d4a-435b-941a-e4c2ad506ca4", "type": "concept", "title": "repair attempts"}], "description": "Why it matters: Students practice tools for naming conflict, reducing escalation, and finding workable next steps."}]}, {"id": "3d45df54-5ec4-42ff-9a1b-60baab771a86", "type": "topic", "title": "Civic Communication Lab and Public Project", "description": "The capstone lab turns theory into practice. Students research a public issue, design an ethical communication intervention, test it with an audience, and reflect on civic impact.", "children": [{"id": "37578f4e-d6b4-490f-a5bb-251f6f975ef6", "type": "subtopic", "title": "Issue brief and audience analysis", "children": [{"id": "fbcb0082-9179-4063-b259-867c3dcd114d", "type": "concept", "title": "problem statement"}, {"id": "0589b4d6-b3b9-4f24-84cf-b888eb5da1e3", "type": "concept", "title": "stakeholder map"}, {"id": "b054fad4-3991-4e40-ba1b-e69e1ffe4b65", "type": "concept", "title": "audience personas"}, {"id": "a1627bb6-93ea-4a2a-902b-46b32c49bff4", "type": "concept", "title": "evidence base"}], "description": "Why it matters: Students define a civic problem and identify publics, stakeholders, constraints, and opportunities."}, {"id": "ab4212d1-8ffc-4958-8551-8853e62f5231", "type": "subtopic", "title": "Message and media design", "children": [{"id": "e2d437f8-5b7d-4824-82c4-39f32e131447", "type": "concept", "title": "message strategy"}, {"id": "a04d3594-3118-4081-ada2-40694f3d8543", "type": "concept", "title": "visual rhetoric"}, {"id": "7aa73919-038a-45e2-b0cb-9847c18aeb21", "type": "concept", "title": "channel plan"}, {"id": "e1d2e801-3d27-4e3c-9c5f-bc4192282dbc", "type": "concept", "title": "accessibility"}], "description": "Why it matters: Students create communication artifacts suited to a civic purpose and public audience."}, {"id": "ef58dc5d-16ab-4662-b92d-9b83ced7371a", "type": "subtopic", "title": "Evaluation and reflection", "children": [{"id": "565b73fc-3ffb-44cf-bf59-26bc7230ec49", "type": "concept", "title": "feedback"}, {"id": "c68bc36f-d1af-46a0-9f0f-d82044951a7f", "type": "concept", "title": "metrics"}, {"id": "107506cf-d707-46ac-bf22-c77b1855f7ba", "type": "concept", "title": "revision"}, {"id": "946fa985-6f81-4a1b-a47c-c24701533721", "type": "concept", "title": "civic reflection"}], "description": "Why it matters: Students assess outcomes and explain what they learned about communication and public life."}]}], "dbBacked": true}$ccivjson$::jsonb,
